const cfg = $('Config').first().json;
const dry = cfg.dry_run === true || cfg.dry_run === 'true';
// у DRY RUN дивимось на найновіший запис (і сухий, і бойовий), у бойовому режимі лише бойові
const last = {}, newest = {};
for (const { json: r } of $input.all()) {
  if (!r.ticket_id) continue;
  if (!newest[r.ticket_id] || String(r.at) > String(newest[r.ticket_id].at)) newest[r.ticket_id] = r;
  if (r.dry_run === true) continue;
  if (!last[r.ticket_id] || String(r.at) > String(last[r.ticket_id].at)) last[r.ticket_id] = r;
}
const out = [];
for (const r of Object.values(dry ? newest : last)) {
  if (!String(r.kind).startsWith('cvat_') || r.kind === 'cvat_escalate' || r.outcome !== 'awaiting_approval') continue;
  let p;
  try { p = JSON.parse(r.payload); } catch (e) { continue; }
  out.push({ json: { ticket_id: r.ticket_id, plan: p, kind: r.kind, prepared_at: r.at, dry_run: dry } });
}
return out;

const cfg = $('Config').first().json;
const words = String(cfg.approve_words).toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const maxAge = Number(cfg.pending_days) * 86400000;
const admins = new Set((($('[Redmine] Get IT Admins').first().json.users) || []).map(u => String(u.id)));
const pend = $('Code: Match Pending').all();
const hist = $('[Redmine] Get Ticket History').all();
const out = [];
pend.forEach(({ json: t }, i) => {
  const r = { ...t, action: 'escalate', reason: '' };
  const h = hist[i] && hist[i].json || {};
  const issue = h.issue || h;
  if (!issue.id) { out.push({ json: { ...r, reason: 'не вдалося прочитати заявку' } }); return; }
  const author = String(issue.author && issue.author.id);
  if ((issue.status && issue.status.is_closed) || ['17', '21'].includes(String(issue.status && issue.status.id))) {
    out.push({ json: { ...r, action: 'cancel', reason: 'задачу закрито без підтвердження' } }); return;
  }
  const isWord = n => words.includes(String(n || '').trim().toLowerCase().replace(/[.!\s]+$/, ''));
  const notes = (issue.journals || []).filter(x => String(x.created_on) > String(t.prepared_at) && isWord(x.notes));
  const ok = notes.filter(x => admins.has(String(x.user && x.user.id)) && String(x.user.id) !== author);
  if (!ok.length) {
    if (notes.length) { out.push({ json: { ...r, reason: `підтвердження написав ${notes[0].user.name}, але він не з «IT Адміни» або є автором заявки` } }); return; }
    if (Date.now() - Date.parse(t.prepared_at) > maxAge) { out.push({ json: { ...r, action: 'cancel', reason: `немає підтвердження понад ${cfg.pending_days} днів` } }); return; }
    return;  // ще чекаємо
  }
  out.push({ json: { ...r, action: 'apply', approved_by: ok[0].user.name } });
});
return out;

const cfg = $('Config').first().json;
const out = [];
// після запису applying на вході рядки аудиту, тому план беремо з рішення Decide Apply
for (const { json: t } of $('Code: Decide Apply').all().filter(i => i.json.action === 'apply' && !i.json.dry_run)) {
  const p = t.plan, space = 'ticket-' + t.ticket_id;
  if (p.action === 'deploy') {
    out.push({ json: { ticket_id: t.ticket_id, plan: p, route: 'deploy', project_name: p.project, email: p.email, server_type: p.type, manager_username: p.login, chat_space: space } });
  } else if (p.action === 'close') {   // інструмент Hetzner просить підтвердження видалення: перший виклик питає, другий відповідає «так» (зі снепшотом)
    out.push({ json: { ticket_id: t.ticket_id, plan: p, route: 'tool', step: 'ask', query: 'delete_server ' + p.server, identifier: '', chat_space: space, chat_text: '' } });
    out.push({ json: { ticket_id: t.ticket_id, plan: p, route: 'tool', step: 'confirm', query: 'delete_server ' + p.server, identifier: '', chat_space: space, chat_text: 'так' } });
  } else {
    out.push({ json: { ticket_id: t.ticket_id, plan: p, route: 'tool', step: 'do', query: (p.action === 'pause' ? 'poweroff ' : 'poweron ') + p.server, identifier: '', chat_space: space, chat_text: '' } });
  }
}
return out;

const saluteOf = t => {  // як звертається автор заявки, якою мовою пише і як його звати
  const desc = String(t.description || '');
  const strip = x => String(x || '').replace(/https?:\/\/\S+|\S+@\S+|\b[\w-]+(?:[._][\w-]+)+\b/g, ' ');
  const txt = strip(desc).length >= 15 ? strip(desc) : strip(String(t.subject || '') + ' ' + desc);
  const cyr = (txt.match(/[\u0400-\u04FF]/g) || []).length, lat = (txt.match(/[A-Za-z]/g) || []).length;
  const lang = lat >= 8 && cyr * 10 < lat ? 'en' : 'uk';  // англійська, якщо кирилиці майже немає
  const s = (desc || String(t.subject || '')).toLowerCase().replace(/^[^\p{L}\p{N}]+/u, '').slice(0, 80);
  let hi;
  if (lang === 'en') hi = /^good\s+morning/.test(s) ? 'Good morning' : /^good\s+afternoon/.test(s) ? 'Good afternoon' : /^good\s+evening/.test(s) ? 'Good evening' : /^hi\b/.test(s) ? 'Hi' : 'Hello';
  else if (/^(доброго\s+ранку|добрий\s+ранок|доброе\s+утро)/.test(s)) hi = 'Доброго ранку';
  else if (/^(добрий\s+день|доброго\s+дня|добрый\s+день)/.test(s)) hi = 'Добрий день';
  else if (/^(добрий\s+вечір|доброго\s+вечора|добрый\s+вечер)/.test(s)) hi = 'Добрий вечір';
  else if (/^(вітаю|здрастуйте|здравствуйте)/.test(s)) hi = 'Вітаю';
  else hi = 'Привіт';
  const nm = String((t.author && t.author.name) || '').trim().split(/\s+/);
  const name = nm.length === 2 && /^[\p{L}'’-]+$/u.test(nm[1]) ? nm[1] : '';  // у Redmine ім'я у форматі «Прізвище Ім'я»; інші формати без імені
  return { lang, hi, name };
};
const _kh = Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Kyiv', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
// звертання, мова й ім'я автора: з Code: Parse Tickets (флоу-інструменти) або з тексту заявки (флоу Apply)
const _salOf = id => {
  try { const p = $('Code: Parse Tickets').all().find(x => String(x.json.ticket_id) === String(id)); if (p && p.json.salute) return p.json.salute; } catch (e) {}
  try { for (const { json: h } of $('[Redmine] Get Ticket History').all()) { const i = h.issue || h; if (String(i.id) === String(id)) return saluteOf(i); } } catch (e) {}
  return { lang: 'uk', hi: 'Привіт', name: '' };
};
// лише для публічних відповідей людям (укр. або англ. за мовою заявки); приватні нотатки для адміністраторів без привітань
const polite = (uk, en, id) => {
  const s = _salOf(id), nm = s.name ? ', ' + s.name : '';
  return s.lang === 'en'
    ? `${s.hi}${nm}! Thank you for your request.\n\n${en || uk}\n\n${_kh < 18 ? 'Have a nice day!' : 'Have a nice evening!'}`
    : `${s.hi}${nm}! Дякуємо за звернення.\n\n${uk}\n\n${_kh < 18 ? 'Гарного дня!' : 'Гарного вечора!'}`;
};

const calls = (() => { try { return $('Code: Build Calls').all(); } catch (e) { return []; } })();
const resOf = (c, k) => { for (const n of ['Execute: Deploy Flow', 'Execute: Hetzner Tool']) { try { const all = $(n).all(); const mine = calls.filter(x => x.json.route === (n.includes('Deploy') ? 'deploy' : 'tool')); const idx = mine.indexOf(c); if (idx >= 0 && all[idx]) return all[idx].json; } catch (e) { } } return null; };
let servers = null;
try { servers = $('[Hetzner] Get Servers').first().json.servers; } catch (e) { }
const rows = [], live = {};
for (const { json: j } of $input.all()) {
  if (!j.action) continue;                         // елементи після виконання не мають поля action: їх береться з calls
  const p = j.plan || {};
  let note, outcome, assign = false, details = j.reason || '';
  if (j.action === 'apply') { outcome = 'dry_applied'; details = p.server; note = `DRY RUN (змін не внесено). Агент виконав би: ${p.action} ${p.server}.`; }
  else if (j.action === 'cancel') { outcome = j.dry_run ? 'dry_cancelled' : 'cancelled'; note = `Агент: дію з CVAT скасовано (${details}). Якщо вона ще потрібна, створіть нову заявку.`; }
  else { outcome = j.dry_run ? 'dry_escalate' : 'escalate'; assign = !j.dry_run; note = `Агент: дію з CVAT не виконано. Причина: ${details}. Потрібна перевірка людиною.`; }
  rows.push({ ticket_id: j.ticket_id, kind: 'cvat_' + (p.action || 'escalate'), note, private: true, close: false, assign, logins: p.server || '', outcome, details, payload: JSON.stringify(p), dry_run: j.dry_run });
}
const byT = {};
for (const c of calls) (byT[c.json.ticket_id] = byT[c.json.ticket_id] || []).push(c);
for (const [tid, cs] of Object.entries(byT)) {
  const p = cs[0].json.plan, last = resOf(cs[cs.length - 1]) || {};
  const exists = Array.isArray(servers) ? servers.some(s => s.name === p.server) : null;
  const msg = String(last.message || last.output || last.error || '').slice(0, 300);
  let ok, uk, en, close = true, detail;
  if (p.action === 'deploy') {
    ok = exists === true; close = false; detail = ok ? `сервер ${p.server} створено, чекаємо встановлення` : 'сервер не створено';
    uk = `Розгортання CVAT запущено. Встановлення займає 10–15 хвилин, після нього на вашу пошту надійде лист з адресою та доступом менеджера проєкту.`;
    en = `The CVAT deployment has started. It takes 10–15 minutes; then you will get an email with the address and the project manager login.`;
  } else if (p.action === 'close') {
    ok = exists === false; detail = ok ? `сервер ${p.server} видалено (зі снепшотом)` : `сервер ще існує. ${msg}`;
    uk = `Сервер CVAT для проєкту видалено (перед цим зроблено знімок на випадок, якщо дані знадобляться).`;
    en = `The CVAT server for the project has been deleted (a snapshot was taken first in case the data is needed).`;
  } else if (p.action === 'pause') {
    ok = last.success === true && exists !== false; detail = ok ? `${p.server} вимкнено` : `не вдалося вимкнути. ${msg}`;
    uk = `Сервер CVAT вимкнено, дані збережено. Щоб увімкнути знову, створіть заявку «Відновлення CVAT».`;
    en = `The CVAT server is switched off and the data is kept. To switch it on again, create a "Restore CVAT" ticket.`;
  } else {
    ok = last.success === true && exists !== false; detail = ok ? `${p.server} увімкнено` : `не вдалося увімкнути. ${msg}`;
    uk = `Сервер CVAT увімкнено. Він може стати доступним через кілька хвилин, прошу перевірити.`;
    en = `The CVAT server is switched on. It can take a few minutes to become available; please check.`;
  }
  if (ok) rows.push({ ticket_id: Number(tid), kind: 'cvat_' + p.action, note: polite(uk, en, Number(tid)), private: false, close, assign: false, logins: p.server, outcome: 'applied', details: detail, payload: JSON.stringify(p), dry_run: false });
  else rows.push({ ticket_id: Number(tid), kind: 'cvat_' + p.action, note: `Агент: дію ${p.action} для ${p.server} виконано не повністю. ${detail}. Потрібна перевірка людиною.`, private: true, close: false, assign: true, logins: p.server, outcome: 'escalate', details: detail, payload: JSON.stringify(p), dry_run: false });
}
return rows.map(r => ({ json: { ...r, at: new Date().toISOString() } }));
